package org.joda.time.format;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.Instant;
import org.joda.time.LocalDate;
import org.joda.time.LocalDateTime;
import org.joda.time.LocalTime;
import org.joda.time.MutableDateTime;
import org.joda.time.ReadWritableInstant;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.format.DateTimeFormatterBuilder;
import org.joda.time.format.DateTimeParser;
import org.joda.time.format.DateTimeParserBucket;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class DateTimeFormatter_parseInto_TriageGen1Test {

    private DateTimeFormatter formatter;
    private ReadWritableInstant mockInstant;
    private DateTimeParser mockParser;
    private Chronology mockChrono;
    private DateTimeZone mockZone;

    @Before
    public void setUp() {
        mockInstant = mock(ReadWritableInstant.class);
        mockParser = mock(DateTimeParser.class);
        mockChrono = mock(Chronology.class);
        mockZone = mock(DateTimeZone.class);

        // Default behavior for instant
        when(mockInstant.getMillis()).thenReturn(0L);
        when(mockInstant.getChronology()).thenReturn(mockChrono);
        when(mockChrono.getZone()).thenReturn(mockZone);
        when(mockZone.getOffset(anyLong())).thenReturn(0);

        // Default behavior for chronology
        when(mockChrono.year()).thenReturn(mockChrono);
        when(mockChrono.withZone(any(DateTimeZone.class))).thenReturn(mockChrono);

        // Setup a formatter using a builder to access the internal parser via requireParser()
        // Since we cannot easily inject a mock parser into a final/private field via constructor 
        // in a real environment without reflection, we simulate the behavior.
        // For this test, we assume the formatter is constructed such that requireParser() returns mockParser.
        formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyy-MM-dd")
                .toFormatter();

        // Use reflection to inject the mock parser if necessary, 
        // but for the sake of this unit test logic, we will mock the formatter's behavior 
        // or assume the environment allows the parser injection.
        // Here we use a spy to override the requireParser method.
        formatter = spy(formatter);
        doReturn(mockParser).when(formatter).requireParser();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseInto_NullInstant_ThrowsException() {
        formatter.parseInto(null, "2023-01-01", 0);
    }

    @Test
    public void testParseInto_Success_WithOffsetParsed() {
        String text = "2023-01-01+01:00";
        int position = 0;
        int expectedNewPos = 11;
        long expectedMillis = 1672534800000L; // Mocked result

        when(mockParser.parseInto(any(DateTimeParserBucket.class), eq(text), eq(position)))
                .thenReturn(expectedNewPos);

        // Mock bucket behavior via the parser's interaction
        // In a real Joda execution, the parser populates the bucket.
        // We simulate the side effect on the bucket via an Answer or by mocking the bucket if possible.
        // Since the bucket is instantiated inside the method, we focus on the state changes.

        // We need to simulate iOffsetParsed = true
        DateTimeFormatter offsetFormatter = formatter.withOffsetParsed();

        // To handle the internal bucket, we simulate the return of the parser.
        // Because we can't mock the 'new DateTimeParserBucket', we rely on the fact that 
        // the method calls bucket.getOffsetInteger(). 
        // This is a limitation of testing methods that instantiate objects locally.
        // However, we can test the logic flow.

        // Note: To fully test this, the bucket would need to be injectable or the parser 
        // would need to be the one controlling the bucket state.

        // For the purpose of this test, we assume the parser logic is tested elsewhere 
        // and we are testing the coordination in parseInto.

        // Since we can't easily mock the local 'new DateTimeParserBucket', 
        // we assume the parser is a mock that handles the bucket.
        doAnswer(invocation -> {
            DateTimeParserBucket bucket = invocation.getArgument(0);
            // Simulate bucket state
            // We can't easily set private fields of bucket, but we can trigger the logic
            // if the bucket was provided. Since it's local, we focus on the lines we can hit.
            return expectedNewPos;
        }).when(mockParser).parseInto(any(DateTimeParserBucket.class), eq(text), eq(position));

        // Execute
        int actualPos = offsetFormatter.parseInto(mockInstant, text, position);

        assertEquals(expectedNewPos, actualPos);
        verify(mockInstant).setMillis(anyLong());
        verify(mockInstant).setChronology(any(Chronology.class));
    }

    @Test
    public void testParseInto_WithZoneSet() {
        String text = "2023-01-01";
        int position = 0;

        // Case: iZone is not null
        DateTimeZone fixedZone = DateTimeZone.UTC;
        DateTimeFormatter zoneFormatter = formatter.withZone(fixedZone);

        when(mockParser.parseInto(any(DateTimeParserBucket.class), eq(text), eq(position)))
                .thenReturn(10);

        zoneFormatter.parseInto(mockInstant, text, position);

        verify(mockInstant).setZone(fixedZone);
    }

    @Test
    public void testParseInto_ChronologySelection() {
        String text = "2023-01-01";
        // Ensure selectChronology (internal) is triggered via the flow
        // We test that the chronology is passed to the bucket and updated in the instant

        when(mockParser.parseInto(any(DateTimeParserBucket.class), eq(text), eq(0)))
                .thenReturn(10);

        formatter.parseInto(mockInstant, text, 0);

        verify(mockInstant).setChronology(any(Chronology.class));
    }

    @Test
    public void testParseInto_DefaultYearLogic() {
        String text = "2023-01-01";
        int pivotYear = 2000;
        DateTimeFormatter pivotFormatter = formatter.withPivotYear(pivotYear);

        when(mockParser.parseInto(any(DateTimeParserBucket.class), eq(text), eq(0)))
                .thenReturn(10);

        pivotFormatter.parseInto(mockInstant, text, 0);

        // Verification of pivot year usage is implicit in the bucket construction
        // which is hard to verify without reflection, but we ensure no crash occurs.
    }

    @Test
    public void testParseInto_WithDefaultYear() {
        String text = "2023-01-01";
        int defaultYear = 2025;
        DateTimeFormatter defYearFormatter = formatter.withDefaultYear(defaultYear);

        when(mockParser.parseInto(any(DateTimeParserBucket.class), eq(text), eq(0)))
                .thenReturn(10);

        defYearFormatter.parseInto(mockInstant, text, 0);
        // Verification of default year usage is implicit.
    }
}
